def word_count_ascii(text: str) -> list:
    words = []
    current = []
    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            current.append(ch)
        else:
            if current:
                words.append(''.join(current).lower())
                current.clear()
    if current:
        words.append(''.join(current).lower())
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    result = sorted([[w, counts[w]] for w in counts], key=lambda x: x[0])
    return result
```

