def word_count_ascii(text: str) -> list[list]:
    words: list[str] = []
    current: list[str] = []
    for ch in text:
        code = ord(ch)
        is_ascii_letter = (65 <= code <= 90) or (97 <= code <= 122)
        if is_ascii_letter:
            if 65 <= code <= 90:
                current.append(chr(code + 32))
            else:
                current.append(ch)
        else:
            if current:
                words.append(''.join(current))
                current.clear()
    if current:
        words.append(''.join(current))
    counts: dict[str, int] = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    pairs: list[list] = [[w, c] for w, c in counts.items()]
    pairs.sort(key=lambda x: x[0])
    return pairs
